-- Store inline chart payloads generated by the local presentation tool.

create table if not exists public.chat_message_charts (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.chat_sessions(id) on delete cascade,
  message_id uuid not null references public.messages(id) on delete cascade,
  run_id uuid not null references public.agent_runs(id) on delete cascade,
  chart_ref text not null,
  insert_token text not null,
  title text not null,
  chart_type text not null,
  payload_json jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint chat_message_charts_type_check
    check (chart_type in ('line', 'bar')),
  constraint chat_message_charts_token_check
    check (insert_token = ('[[krw-chart:' || chart_ref || ']]'))
);

create unique index if not exists uq_chat_message_charts_message_ref
  on public.chat_message_charts (message_id, chart_ref);

create index if not exists idx_chat_message_charts_session_created
  on public.chat_message_charts (session_id, created_at);

create index if not exists idx_chat_message_charts_message
  on public.chat_message_charts (message_id);

create index if not exists idx_chat_message_charts_run
  on public.chat_message_charts (run_id);

alter table public.chat_message_charts enable row level security;

revoke all on table public.chat_message_charts from anon, authenticated;
grant select on table public.chat_message_charts to authenticated;
grant select, insert, update, delete on table public.chat_message_charts to service_role;

drop policy if exists "chat_message_charts_select_own" on public.chat_message_charts;
create policy "chat_message_charts_select_own" on public.chat_message_charts
  for select using (public.session_owner(session_id) = auth.uid());

drop policy if exists "chat_message_charts_insert_own" on public.chat_message_charts;
create policy "chat_message_charts_insert_own" on public.chat_message_charts
  for insert with check (public.session_owner(session_id) = auth.uid());

drop policy if exists "chat_message_charts_update_own" on public.chat_message_charts;
create policy "chat_message_charts_update_own" on public.chat_message_charts
  for update using (public.session_owner(session_id) = auth.uid())
  with check (public.session_owner(session_id) = auth.uid());
